-- Baseline generado desde el schema real que produce Hibernate a partir de las 25 entidades JPA actuales (jakarta.persistence.schema-generation.scripts.action=create). No escrito a mano: es el punto de partida versionado a partir del cual se aplican los fixes de integridad en las migraciones siguientes.
-- events.day/month/year -> date (LocalDate), y study_program.year/term.year -> year_number: "day"/"month"/"year" son palabras reservadas en H2 y su uso sin comillas impedía crear esas 3 tablas bajo el create-drop implícito que usaba la app hasta ahora (hallazgo detectado al generar este baseline, no estaba en el análisis original).

create table address (id bigint generated by default as identity, city varchar(255), country varchar(255), floor varchar(255), number varchar(255), postal_code varchar(255), state varchar(255), street varchar(255), primary key (id));
create table course (capacity integer, duration_months integer, price numeric(38,2), status boolean, id bigint generated by default as identity, registration_end timestamp(6), registration_start timestamp(6), term_id bigint, name varchar(255), schedule varchar(255), primary key (id));
create table course_enrollment (completion_date timestamp(6), course_id bigint, enrollment_date timestamp(6), id bigint generated by default as identity, student_id bigint, status varchar(30), primary key (id));
create table course_section (capacity integer, status boolean, course_subject_id bigint not null, created_at timestamp(6), evaluation_scheme_id bigint, id bigint generated by default as identity, instructor_id bigint, term_id bigint not null, schedule varchar(255), primary key (id));
create table course_section_enrollment (attempt_number integer, final_score float(53), course_enrollment_id bigint not null, course_section_id bigint not null, dropped_at timestamp(6), enrolled_at timestamp(6), id bigint generated by default as identity, student_id bigint not null, final_grade_type varchar(255), status varchar(30), primary key (id), constraint uk_course_sec_enr_student_section unique (student_id, course_section_id));
create table course_section_instructor (hours_per_week integer, course_section_id bigint not null, end_at timestamp(6), id bigint generated by default as identity, instructor_id bigint not null, start_at timestamp(6), notes varchar(500), role varchar(30) not null, primary key (id));
create table course_subject (curricular_year integer, sort_order integer, status boolean, weekly_workload integer, course_id bigint, id bigint generated by default as identity, name varchar(255), qualification_type varchar(255), curricular_term varchar(30), subject_recurrence varchar(30), primary key (id));
create table course_subject_prerequisite (min_grade float(53), course_subject_id bigint not null, id bigint generated by default as identity, prerequisite_course_subject_id bigint not null, notes varchar(500), requirement_type varchar(30) not null, primary key (id), constraint uk_course_prereq_target_req unique (course_subject_id, prerequisite_course_subject_id, requirement_type));
create table evaluation_scheme (exam_count_expected integer, final_exam float(53), final_exam_recovery_first_attempt float(53), final_exam_recovery_second_attempt float(53), final_exam_recovery_third_attempt float(53), final_weight float(53), first_exam float(53), first_exam_recovery float(53), general_average float(53), has_final boolean, second_exam float(53), second_exam_recovery float(53), third_exam float(53), third_exam_recovery float(53), tp_count_expected integer, id bigint generated by default as identity, notes varchar(1000), name varchar(255), aggregation_method varchar(30), primary key (id));
create table events (date date, course_id bigint, event_id bigint generated by default as identity, description varchar(255), name varchar(255), primary key (event_id));
create table grade_item (max_score float(53), score float(53), sequence_number integer, weight float(53), course_section_enrollment_id bigint, date timestamp(6), id bigint generated by default as identity, program_section_enrollment_id bigint, comments varchar(255), type varchar(30) not null, primary key (id));
create table institution (pref_asignar_curso boolean, pref_calendario boolean, pref_notas boolean, address_id bigint unique, id bigint generated by default as identity, email varchar(255), facebook varchar(255), name varchar(255), phone_number varchar(255), secondary_phone_number varchar(255), sms_password varchar(255), sms_url varchar(255), sms_usuario varchar(255), tweeter varchar(255), website varchar(255), primary key (id));
create table instructor (id bigint generated by default as identity, person_id bigint unique, primary key (id));
create table person (grant_system_access boolean, status smallint check (status between 0 and 2), address_id bigint unique, id bigint generated by default as identity, rol_id bigint, dni varchar(255), email varchar(255), file varchar(255), last_name varchar(255), name varchar(255), nationality varchar(255), password varchar(255), sex varchar(255), primary key (id));
create table program (price numeric(38,2), status boolean, total_years integer, id bigint generated by default as identity, name varchar(255), primary key (id));
create table program_enrollment (completion_date timestamp(6), enrollment_date timestamp(6), id bigint generated by default as identity, program_id bigint, student_id bigint, status varchar(30), primary key (id));
create table program_section (capacity integer, status boolean, created_at timestamp(6), evaluation_scheme_id bigint, id bigint generated by default as identity, instructor_id bigint, program_subject_id bigint not null, term_id bigint not null, schedule varchar(255), primary key (id));
create table program_section_enrollment (attempt_number integer, final_score float(53), dropped_at timestamp(6), enrolled_at timestamp(6), id bigint generated by default as identity, program_enrollment_id bigint not null, program_section_id bigint not null, student_id bigint not null, final_grade_type varchar(255), status varchar(30), primary key (id), constraint uk_prog_sec_enr_student_section unique (student_id, program_section_id));
create table program_section_instructor (hours_per_week integer, end_at timestamp(6), id bigint generated by default as identity, instructor_id bigint not null, program_section_id bigint not null, start_at timestamp(6), notes varchar(500), role varchar(30) not null, primary key (id));
create table program_subject (curricular_year integer, sort_order integer, status boolean, id bigint generated by default as identity, program_id bigint, name varchar(255), curricular_term varchar(30), subject_recurrence varchar(30), primary key (id));
create table program_subject_prerequisite (min_grade float(53), id bigint generated by default as identity, prerequisite_program_subject_id bigint not null, program_subject_id bigint not null, notes varchar(500), requirement_type varchar(30) not null, primary key (id), constraint uk_prog_prereq_target_req unique (program_subject_id, prerequisite_program_subject_id, requirement_type));
create table student (defaulter boolean, grant_final_exam_sign_up boolean, id bigint generated by default as identity, institution_id bigint, person_id bigint unique, primary key (id));
create table study_program (status boolean, year_number integer, id bigint generated by default as identity, program_id bigint, description varchar(255), grade varchar(255), primary key (id));
create table study_program_course (status boolean, course_id bigint, id bigint generated by default as identity, study_program_id bigint, primary key (id));
create table term (status boolean, year_number integer, end_date timestamp(6), id bigint generated by default as identity, start_date timestamp(6), description varchar(255), type varchar(255), primary key (id));
